begin;
set local search_path=public,extensions;
select plan(20);
select ok(not has_function_privilege('anon','public.save_admin_menu_category(jsonb)','EXECUTE'),'anonymous category save forbidden');
select ok(not has_function_privilege('anon','public.save_admin_menu_prices(jsonb)','EXECUTE'),'anonymous quick price save forbidden');
select ok(not has_function_privilege('anon','public.save_admin_event_with_branches(uuid,timestamptz,jsonb,uuid[],jsonb,text)','EXECUTE'),'anonymous event save forbidden');
insert into auth.users(id) values('10000000-0000-4000-8000-000000000011'),('10000000-0000-4000-8000-000000000012');
insert into profiles(id,display_name,role) values('10000000-0000-4000-8000-000000000011','TEST_unified_admin','admin'),('10000000-0000-4000-8000-000000000012','TEST_unified_editor','editor') on conflict(id) do update set role=excluded.role;
insert into branches(id,code,slug,name,address_line,district,city,maps_url,status,is_active) values('20000000-0000-4000-8000-000000000011','TESTUNI','test-unified-branch','TEST_Unified_Branch','TEST_Address','TEST_District','TEST_City','https://example.test/maps','published',true);
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000012',true);
set local role authenticated;
select throws_ok($$select save_admin_menu_category('{}')$$,'42501','admin_required','editor category save forbidden');
select throws_ok($$select save_admin_menu_prices('{}')$$,'42501','admin_required','editor quick price save forbidden');
select throws_ok($$select save_admin_event_with_branches(null,null,'{}','{}','[]','')$$,'42501','admin_required','editor event save forbidden');
reset role;
select set_config('request.jwt.claim.sub','10000000-0000-4000-8000-000000000011',true);
set local role authenticated;
select save_admin_menu_category('{"name":"TEST_Category","slug":"test-unified-category","status":"published","is_active":true,"sort_order":0,"confirmed":"EVET","branches":["20000000-0000-4000-8000-000000000011"]}');
select ok(exists(select 1 from menu_categories c join menu_category_branches b on b.category_id=c.id where c.slug='test-unified-category' and b.branch_id='20000000-0000-4000-8000-000000000011'),'category and branch saved together');
select throws_ok($$select save_admin_menu_category('{"name":"TEST_Failed","slug":"test-failed-category","status":"draft","is_active":true,"sort_order":1,"branches":["20000000-0000-4000-8000-000000000011","20000000-0000-4000-8000-000000000099"]}')$$,'23503','branch_not_found','invalid branch rejects category transaction');
select is((select count(*) from menu_categories where slug='test-failed-category'),0::bigint,'category creation rolls back fully');
create temp table test_category_payload(payload jsonb);
insert into test_category_payload select jsonb_build_object('id',c.id,'updated_at',c.updated_at,'name',c.name,'status',c.status,'is_active',c.is_active,'sort_order',c.sort_order,'branches',jsonb_build_array('20000000-0000-4000-8000-000000000011'),'branch_snapshot',(select jsonb_agg(jsonb_build_object('id',b.id,'updated_at',b.updated_at)) from menu_category_branches b where b.category_id=c.id)) from menu_categories c where slug='test-unified-category';
select throws_ok($$select save_admin_menu_category((select payload || '{"updated_at":"2000-01-01T00:00:00Z"}' from test_category_payload))$$,'40001','stale_category','stale category save rejected');
insert into menu_items(id,category_id,slug,name,status,is_active) select '30000000-0000-4000-8000-000000000011',id,'test-price-product','TEST_Price_Product','published',true from menu_categories where slug='test-unified-category';
insert into menu_item_branches(id,menu_item_id,branch_id,price_cents,price_note,is_active) values('40000000-0000-4000-8000-000000000011','30000000-0000-4000-8000-000000000011','20000000-0000-4000-8000-000000000011',10000,'TEST_keep',false);
insert into menu_item_variants(id,menu_item_branch_id,slug,label,price_cents,price_note,metadata) values('50000000-0000-4000-8000-000000000011','40000000-0000-4000-8000-000000000011','test-size','TEST_Size',21500,'TEST_note','{"keep":"TEST_value"}');
create temp table test_price_payload(payload jsonb);
insert into test_price_payload select jsonb_build_object('id','30000000-0000-4000-8000-000000000011','branches',jsonb_build_array(jsonb_build_object('id',b.id,'updated_at',b.updated_at,'price_cents',15000)),'variants',jsonb_build_array(jsonb_build_object('id',v.id,'updated_at',v.updated_at,'price_cents',25000))) from menu_item_branches b join menu_item_variants v on v.menu_item_branch_id=b.id where b.id='40000000-0000-4000-8000-000000000011';
select save_admin_menu_prices((select payload from test_price_payload));
select ok((select price_cents=15000 and price_note='TEST_keep' and not is_active from menu_item_branches where id='40000000-0000-4000-8000-000000000011'),'quick edit preserves branch notes and visibility');
select ok((select price_cents=25000 and price_note='TEST_note' and metadata->>'keep'='TEST_value' from menu_item_variants where id='50000000-0000-4000-8000-000000000011'),'quick edit preserves option notes and metadata');
select throws_ok($$select save_admin_menu_prices((select jsonb_set(jsonb_set(payload,'{branches,0,price_cents}','99000'),'{variants,0,updated_at}','"2000-01-01T00:00:00Z"') from test_price_payload))$$,'40001','stale_price','stale child aborts the whole price transaction');
select ok((select price_cents=15000 from menu_item_branches where id='40000000-0000-4000-8000-000000000011'),'failed price edit rolls back earlier branch change');
select save_admin_event_with_branches(null,null,'{"slug":"test-unified-event","title":"TEST_Event","description":"TEST_Description","content_type":"event","start_at":"2099-01-01T18:00:00Z","status":"published","is_active":true,"is_featured":false}',array['20000000-0000-4000-8000-000000000011'::uuid],'[]','YAYINLA');
select ok(exists(select 1 from events e join event_branches b on b.event_id=e.id where e.slug='test-unified-event' and b.branch_id='20000000-0000-4000-8000-000000000011'),'event and branch saved together');
select throws_ok($$select save_admin_event_with_branches(null,null,'{"slug":"test-failed-event","title":"TEST_Event","description":"TEST_Description","content_type":"event","start_at":"2099-01-01T18:00:00Z","status":"draft","is_active":true}',array['20000000-0000-4000-8000-000000000099'::uuid],'[]','')$$,'23503','insert or update on table "event_branches" violates foreign key constraint "event_branches_branch_id_fkey"','invalid event branch aborts transaction');
select is((select count(*) from events where slug='test-failed-event'),0::bigint,'event insert rolls back with its branches');
select throws_ok($$select save_admin_event_with_branches(null,null,'{"slug":"test-unconfirmed-event","title":"TEST_Event","description":"TEST_Description","content_type":"event","start_at":"2099-01-01T18:00:00Z","status":"published","is_active":true}',array['20000000-0000-4000-8000-000000000011'::uuid],'[]','')$$,'22023','visibility_confirmation_required','event publishing requires confirmation');
select ok(exists(select 1 from admin_activity_logs where entity_label='TEST_Event'),'event writes preserve audit log');
select ok(exists(select 1 from admin_activity_logs where entity_label='TEST_Category'),'category save preserves audit log');
reset role;
select * from finish();
rollback;
